"""Every case in conformance/document-ops.v1.json, generated by the TypeScript editor."""

import json
import unittest
from pathlib import Path

from super_editor import diff_documents, summarize_revision, text_parts

DATA = json.loads((Path(__file__).resolve().parents[3] / "conformance" / "document-ops.v1.json").read_text())


class DocumentOps(unittest.TestCase):
    def test_text_parts(self) -> None:
        self.assertGreaterEqual(len(DATA["text_parts"]), 150)
        for i, case in enumerate(DATA["text_parts"]):
            with self.subTest(i=i):
                self.assertEqual(text_parts(case["content"]), case["expect"])

    def test_diff(self) -> None:
        self.assertGreaterEqual(len(DATA["diff"]), 150)
        for i, case in enumerate(DATA["diff"]):
            with self.subTest(i=i):
                self.assertEqual(diff_documents(case["a"], case["b"]), case["expect"])

    def test_summarize_revision(self) -> None:
        self.assertGreaterEqual(len(DATA["summarize_revision"]), 150)
        for i, case in enumerate(DATA["summarize_revision"]):
            with self.subTest(i=i):
                self.assertEqual(summarize_revision(case["revision"]), case["expect"])


if __name__ == "__main__":
    unittest.main()
